2) JS, in the main section after buildControls() and the #setup open line (about line 3927):
```
(function () {
  const aside = $('.panel-controls');
  const btn = el('button', { type: 'button', class: 'more-below' });
  btn.tabIndex = -1; btn.setAttribute('aria-hidden', 'true'); // keyboard focus already scrolls the box
  aside.append(btn);
  const parts = [['Ground', '#ground-sec'], ['Their powers', '#powers']];
  const check = () => {
    const more = aside.scrollHeight - aside.clientHeight - aside.scrollTop > 4;
    aside.classList.toggle('has-more', more);
    if (more) { const bottom = aside.getBoundingClientRect().bottom; const hidden = parts.filter(([, s]) => $(s).getBoundingClientRect().top > bottom - 40).map(([n]) => n); btn.textContent = 'More below' + (hidden.length ? ': ' + hidden.join(', ') : '') + ' ↓'; }
  };
  btn.addEventListener('click', () => aside.scrollTo({ top: aside.scrollHeight }));
  aside.addEventListener('scroll', check, { passive: true });
  addEventListener('resize', check);
  for (const c of aside.children) new ResizeObserver(check).observe(c); // details toggles, hint and dial text changes
  check();
})();
```

